const api=window.location.pathname.replace(/\/[^/]*$/,'').replace(/\/$/,'')+'/api/v1';
let me, records=[], tab='search', query='', modal=null, selected=null, batchId=null;
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const full=r=>`${r.firstName} ${r.middleName?r.middleName+' ':''}${r.lastName}`;
async function apiCall(path,opt={}){let r=await fetch(api+path,{credentials:'same-origin',headers:{...(opt.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(opt.headers||{})},...opt});let body=await r.json().catch(()=>({error:'Server returned an invalid response'}));if(!r.ok)throw Error(body.error||'Request failed');return body}
function badge(s){let m={Baptism:'bg-navy-800/10 text-navy-800 border-navy-800/30',Confirmation:'bg-gold-100 text-gold-700 border-gold-400/50',Marriage:'bg-wine-100 text-wine-700 border-wine-600/30',Communion:'bg-slate2-100 text-slate2-700 border-slate2-300',Death:'bg-slate-200 text-slate-600 border-slate-300'};return `<span class="px-2 py-0.5 rounded-full text-xs font-semibold border ${m[s]||''}">${esc(s)}</span>`}
function login(){app.innerHTML=`<main class="min-h-screen grid place-items-center px-5"><section class="w-full max-w-md bg-white border border-slate2-300/70 rounded-lg p-7 shadow-sm"><div class="w-10 h-10 rounded-full border border-gold-400 text-gold-400 grid place-items-center mb-5 font-cert">✝</div><h1 class="text-xl font-semibold">Parish Sacramental Registry</h1><p class="text-sm text-slate2-500 mt-1 mb-6">Diocesan Record & Certification Office</p><form id="loginForm" class="space-y-4"><div><label class="field-label block mb-1">USERNAME</label><input class="w-full border border-slate2-300 rounded-md p-2.5" name="username" required></div><div><label class="field-label block mb-1">PASSWORD</label><input class="w-full border border-slate2-300 rounded-md p-2.5" name="password" type="password" required></div><button class="w-full bg-navy-800 text-white rounded-md py-2.5 text-sm font-semibold">Sign in</button></form></section></main>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();try{me=(await apiCall('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))})).data;render()}catch(x){alert(x.message)}}}
function shell(){let tabs=[['search','Search & Print Certificates'],['bulk','Bulk Data Ingestion'],['rapid','Rapid Data Entry'],['audit','Issuance Audit Logs']];return `<header class="bg-navy-950 border-b border-navy-700 no-print"><div class="max-w-7xl mx-auto px-6 pt-5"><div class="flex justify-between items-center mb-5"><div class="flex gap-3 items-center"><div class="w-9 h-9 rounded-full border border-gold-400/60 text-gold-400 grid place-items-center font-cert">✝</div><div><h1 class="text-slate-50 text-lg font-semibold leading-none">Parish Sacramental Registry System</h1><p class="text-xs mt-1 text-slate-400">Diocesan Record &amp; Certification Office</p></div></div><div class="text-sm text-slate2-300"><span class="inline-block w-2 h-2 bg-green-400 rounded-full mr-2"></span>Logged in as: <b class="text-white">${esc(me.full_name)}</b> <button id="logout" class="ml-3 underline">Logout</button></div></div><nav class="flex gap-7 text-sm">${tabs.filter(t=>me.role!=='viewer'||['search','audit'].includes(t[0])).map(t=>`<button data-tab="${t[0]}" class="tab ${tab===t[0]?'active':'text-slate-300'} pb-3 font-medium">${t[1]}</button>`).join('')}</nav></div></header><main class="max-w-7xl mx-auto px-6 py-8 no-print" id="content"></main>`}
async function render(){app.innerHTML=shell();$('#logout').onclick=async()=>{await apiCall('/auth/logout',{method:'POST'});me=null;login()};document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{tab=x.dataset.tab;render()});if(tab==='search')searchView();if(tab==='rapid')rapidView();if(tab==='bulk')bulkView();if(tab==='audit')auditView()}
async function getRecords(){records=(await apiCall('/records?q='+encodeURIComponent(query))).data}
async function searchView(){await getRecords();content.innerHTML=`<section><h2 class="text-xl font-semibold">Search Sacramental Records</h2><p class="text-sm text-slate2-500 mt-1 mb-5">Look up by name, date of birth, sacrament type, or book/page/line reference.</p><div class="bg-white border border-slate2-300/70 rounded-lg p-4 mb-5 shadow-sm"><div class="relative"><span class="absolute left-3 top-2.5 text-slate2-500">⌕</span><input id="query" value="${esc(query)}" class="w-full bg-paper border border-slate2-300 rounded-md pl-9 p-2.5 text-sm" placeholder="Search e.g. Santos, 1998-03-12, Baptism, 12/45..."></div></div><div class="bg-white border border-slate2-300/70 rounded-lg shadow-sm overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-navy-900 text-slate-200 text-left"><tr><th class="px-4 py-3 text-xs">NAME</th><th class="px-4 py-3 text-xs">SACRAMENT</th><th class="px-4 py-3 text-xs">EVENT DATE</th><th class="px-4 py-3 text-xs">BOOK / PAGE / LINE</th><th class="px-4 py-3"></th></tr></thead><tbody>${records.map(r=>`<tr class="border-b border-slate2-100 hover:bg-paper/70"><td class="p-4 font-medium">${esc(full(r))}<small class="block text-slate2-500 font-normal">DOB ${esc(r.dob||'—')}</small></td><td class="p-4">${badge(r.sacrament)}</td><td class="p-4">${esc(r.eventDate)}</td><td class="p-4 font-mono text-xs">Bk ${esc(r.book)} / Pg ${esc(r.page)} / Ln ${esc(r.line)}</td><td class="p-4 text-right"><button data-issue="${r.id}" class="bg-navy-800 text-white px-3 py-1.5 rounded-md text-xs font-semibold">Issue Certificate</button></td></tr>`).join('')||'<tr><td colspan="5" class="p-10 text-center text-slate2-500">No records match your search.</td></tr>'}</tbody></table></div><div class="px-4 py-2.5 bg-paper border-t text-xs text-slate2-500">${records.length} record${records.length===1?'':'s'} shown</div></div></section>`;$('#query').oninput=async e=>{query=e.target.value;await searchView();$('#query').focus();$('#query').setSelectionRange(query.length,query.length)};document.querySelectorAll('[data-issue]').forEach(b=>b.onclick=()=>certificatePreview(records.find(r=>r.id==b.dataset.issue)))}
function issueModal(r){selected=r;modal='issue';app.insertAdjacentHTML('beforeend',`<div id="overlay" class="fixed inset-0 bg-ink/60 grid place-items-center z-20 px-4"><section class="bg-white rounded-lg shadow-2xl w-full max-w-md"><div class="p-5 border-b flex justify-between"><h3 class="font-semibold">Issue Certificate</h3><button data-close>×</button></div><div class="p-6 space-y-4"><div class="bg-paper border rounded-md p-3 text-sm"><b>${esc(full(r))}</b><p class="text-xs text-slate2-500 mt-1">${r.sacrament} · Bk ${r.book}/Pg ${r.page}/Ln ${r.line}</p></div><div><label class="field-label block mb-1">REQUESTOR NAME</label><input id="requestor" class="w-full border rounded-md p-2" value="${esc(full(r))}"></div><div><label class="field-label block mb-1">PURPOSE OF ISSUANCE</label><select id="purpose" class="w-full border rounded-md p-2"><option>Personal Record</option><option>Marriage Preparation</option><option>School Requirement</option><option>Employment</option><option>Travel/Passport</option><option>Other</option></select></div></div><div class="p-4 border-t flex justify-end gap-2"><button data-close class="px-4 py-2 text-sm">Cancel</button><button id="preview" class="bg-gold-600 text-white px-4 py-2 rounded-md text-sm font-semibold">Print Preview</button></div></section></div>`);document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);$('#preview').onclick=issue}
async function issue(){try{let x=await apiCall(`/records/${selected.id}/issue`,{method:'POST',body:JSON.stringify({requestor_name:$('#requestor').value,purpose:$('#purpose').value})});let url=`${api}/records/${selected.id}/certificate.pdf?log_id=${x.data.id}`;closeModal();certificatePreview(url)}catch(e){alert(e.message)}}
function certificatePreview(r){selected=r;let title={Baptism:'Certificate of Baptism',Confirmation:'Certificate of Confirmation',Marriage:'Certificate of Marriage',Communion:'Certificate of First Holy Communion',Death:'Certificate of Death'}[r.sacrament]||'Sacramental Certificate';let date=v=>v?new Date(v+'T00:00:00').toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'}):'—';let name=esc(full(r));let body=r.sacrament==='Marriage'?`This is to certify that <strong>${name}</strong> and <strong>${esc(r.spouse)}</strong> were joined in Holy Matrimony according to the rites of the Roman Catholic Church on <strong>${date(r.eventDate)}</strong>, as attested by the Sacramental Registers of this Parish.`:r.sacrament==='Death'?`This is to certify that <strong>${name}</strong>, born on <strong>${date(r.dob)}</strong> to <strong>${esc(r.fatherName)}</strong> and <strong>${esc(r.motherName)}</strong>, departed this life on <strong>${date(r.eventDate)}</strong> and was given ecclesiastical rites according to the Roman Catholic Church.`:`This is to certify that <strong>${name}</strong>, born on <strong>${date(r.dob)}</strong> to <strong>${esc(r.fatherName)}</strong> and <strong>${esc(r.motherName)}</strong>, received the Sacrament of <strong>${esc(r.sacrament)}</strong> in this Parish on <strong>${date(r.eventDate)}</strong>, according to the Rites of the Roman Catholic Church.`;let notes=r.marginNotes?`<div class="mb-6 text-sm bg-wine-100 border-l-[3px] border-wine-700 p-3"><b class="block text-xs text-wine-700">CANONICAL MARGIN NOTES</b>${esc(r.marginNotes)}</div>`:'';app.insertAdjacentHTML('beforeend',`<div id="certificate-preview" class="fixed inset-0 bg-ink/70 z-30 px-4 py-8 overflow-y-auto"><section class="max-w-3xl mx-auto"><div class="flex justify-end gap-2 mb-3"><button data-close-preview class="px-4 py-2 text-sm rounded-md bg-navy-800 text-white font-medium">Close</button><button id="print-certificate" class="px-4 py-2 text-sm rounded-md bg-gold-600 text-white font-semibold">Print Certificate</button></div><article class="bg-white shadow-2xl mx-auto p-12 md:p-14 font-cert text-[#1c2431]" style="max-width:720px"><header class="text-center border-b-2 border-gold-600 pb-5 mb-6"><p class="text-xs tracking-wide text-wine-700">DIOCESE OF SAN ILDEFONSO</p><h2 class="text-2xl font-semibold mt-1">Parish of Our Lady of the Assumption</h2><p class="text-xs mt-1 text-slate2-500">Cebu City, Philippines · Est. 1854</p></header><div class="seal mx-auto mb-5"><div>PARISH<br>SEAL</div></div><h3 class="text-center text-xl font-semibold mb-6 tracking-wide">${title}</h3><p class="text-[15px] leading-8 text-justify">${body}</p><div class="grid grid-cols-3 gap-3 my-7 py-3 border-y border-[#d8d2c2] text-sm"><div><span class="block text-xs text-slate2-500">Book No.</span><b>${esc(r.book)}</b></div><div><span class="block text-xs text-slate2-500">Page No.</span><b>${esc(r.page)}</b></div><div><span class="block text-xs text-slate2-500">Line Entry No.</span><b>${esc(r.line)}</b></div></div>${notes}<div class="flex items-end justify-between mt-14 text-sm"><div><div class="border-t border-ink w-56 mb-1"></div><b>${esc(r.minister)}</b><p class="text-xs text-slate2-500">Officiating Priest / Parish Priest</p></div><div class="text-right"><div class="border-t border-ink w-40 mb-1 ml-auto"></div><p class="text-xs text-slate2-500">Date Issued</p><b>${date(new Date().toISOString().slice(0,10))}</b></div></div><p class="text-center text-xs mt-10 pt-4 border-t border-dashed border-slate2-300 text-slate2-500">Issued to <b class="text-ink">____________________</b> for the purpose of <b class="text-ink">Personal Record</b>. Not valid without the parish dry seal.</p></article></section></div>`);$('[data-close-preview]').onclick=()=>$('#certificate-preview').remove();$('#print-certificate').onclick=()=>issuePreview()}
async function issuePreview(){let printWindow=window.open('','_blank');try{let x=await apiCall(`/records/${selected.id}/issue`,{method:'POST',body:JSON.stringify({requestor_name:'Not specified',purpose:'Personal Record'})});let url=`${api}/records/${selected.id}/certificate.pdf?log_id=${x.data.id}`;if(printWindow)printWindow.location=url;else window.location.assign(url)}catch(e){printWindow?.close();alert(e.message)}}
function closeModal(){$('#overlay')?.remove()}
function fields(){return ['sacrament','gender','dob','eventDate','firstName','middleName','lastName','fatherName','motherName','book','page','line','minister','sponsors','marginNotes','spouse']}
function rapidView(){content.innerHTML=`<section><h2 class="text-xl font-semibold">Rapid Data Entry</h2><p class="text-sm text-slate2-500 mt-1 mb-5">Optimized for keyboard-only transcription of physical register books.</p><form id="entry" class="bg-white border border-slate2-300/70 rounded-lg shadow-sm p-6"><div class="grid grid-cols-1 md:grid-cols-4 gap-4">${fields().map(f=>f==='sacrament'?`<div><label class="field-label block mb-1">SACRAMENT TYPE</label><select name="sacrament" class="w-full border border-slate2-300 rounded-md p-2 text-sm"><option>Baptism</option><option>Communion</option><option>Confirmation</option><option>Marriage</option><option>Death</option></select></div>`:f==='gender'?`<div><label class="field-label block mb-1">GENDER</label><select name="gender" class="w-full border border-slate2-300 rounded-md p-2 text-sm"><option>Female</option><option>Male</option></select></div>`:`<div class="${f==='marginNotes'?'md:col-span-4':''}"><label class="field-label block mb-1">${f.replace(/([A-Z])/g,' $1').toUpperCase()}</label><input name="${f}" ${['dob','eventDate'].includes(f)?'type="date"':''} class="w-full border border-slate2-300 rounded-md p-2 text-sm ${['book','line'].includes(f)?'bg-gold-100/40':''}"></div>`).join('')}</div><div class="flex justify-between mt-5 pt-4 border-t"><p class="text-xs text-slate2-500">Press Enter to save and jump to next entry.</p><button class="bg-navy-800 text-white px-5 py-2.5 rounded-md text-sm font-semibold">Save & Next Entry →</button></div></form><div id="toast" class="hidden mt-4 p-3 rounded-md text-sm"></div></section>`;$('#entry').onsubmit=saveRecord}
async function saveRecord(e){e.preventDefault();try{let x=await apiCall('/records',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});let book=e.target.book.value;e.target.reset();e.target.book.value=x.meta.next_book_number||book;e.target.line.value=x.meta.next_line_number;toast('Record saved. Ready for the next entry.',true);e.target.firstName.focus()}catch(x){toast(x.message,false)}} function toast(m,ok){let t=$('#toast');t.textContent=m;t.className=`mt-4 p-3 rounded-md text-sm ${ok?'bg-green-50 border border-green-200 text-green-800':'bg-wine-100 border border-wine-600/30 text-wine-700'}`}
function bulkView(){content.innerHTML=`<section><h2 class="text-xl font-semibold">Bulk Data Ingestion</h2><p class="text-sm text-slate2-500 mt-1 mb-5">Upload a CSV to validate and stage records before committing.</p><div class="grid md:grid-cols-3 gap-5"><div id="drop" class="md:col-span-2 bg-white border-2 border-dashed border-slate2-300 rounded-lg p-10 text-center"><p class="text-slate2-700 font-medium">Drop your CSV file here</p><p class="text-xs text-slate2-500 mt-1 mb-4">or click to browse from your computer</p><input id="file" type="file" accept=".csv" class="hidden"><button id="browse" class="bg-navy-800 text-white px-4 py-2 rounded-md text-sm font-semibold">Choose File</button></div><aside class="bg-white border rounded-lg p-5"><b class="text-sm">Need the format?</b><p class="text-xs text-slate2-500 mt-2 mb-4">Download the approved template with the exact columns expected by the importer.</p><a href="${api}/imports/template" class="text-sm font-semibold text-gold-700 hover:text-gold-600">Download CSV Template ↓</a></aside></div><div id="staging" class="mt-5"></div></section>`;$('#browse').onclick=()=>$('#file').click();$('#file').onchange=upload;$('#drop').ondragover=e=>e.preventDefault();$('#drop').ondrop=e=>{e.preventDefault();upload({target:{files:e.dataTransfer.files}})} }
async function upload(e){let f=new FormData();f.append('file',e.target.files[0]);try{let x=await apiCall('/imports',{method:'POST',body:f});batchId=x.data.batch_id;$('#staging').innerHTML=`<div class="bg-white border rounded-lg overflow-hidden"><table class="w-full text-sm"><thead class="bg-navy-900 text-slate-200"><tr><th class="p-3 text-left">ROW</th><th class="p-3 text-left">STATUS</th><th class="p-3 text-left">DETAIL</th></tr></thead><tbody>${x.data.rows.map(r=>`<tr class="border-b ${r.status==='Valid'?'':'bg-wine-100/30'}"><td class="p-3">${r.row}</td><td class="p-3"><span class="${r.status==='Valid'?'text-green-700':'text-wine-700'}">● ${r.status}</span></td><td class="p-3">${esc(r.errors.join(', ')||'Ready to commit')}</td></tr>`).join('')}</tbody></table><div class="p-3 bg-paper flex justify-end"><button id="commit" class="bg-gold-600 text-white px-4 py-2 rounded-md text-xs font-semibold">Commit Valid Records</button></div></div>`;$('#commit').onclick=commit}catch(x){alert(x.message)}} async function commit(){try{let x=await apiCall(`/imports/${batchId}/commit`,{method:'POST'});alert(`${x.data.committed_rows} records committed.`);tab='search';render()}catch(e){alert(e.message)}}
async function auditView(){let x=await apiCall('/issuance-logs');content.innerHTML=`<section><h2 class="text-xl font-semibold">Issuance Audit Log</h2><p class="text-sm text-slate2-500 mt-1 mb-5">Read-only record of every certificate issued through this system.</p><div class="bg-white border rounded-lg overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-navy-900 text-slate-200"><tr><th class="p-3 text-left">LOG ID</th><th class="p-3 text-left">PERSON NAME</th><th class="p-3 text-left">SACRAMENT</th><th class="p-3 text-left">ISSUED TO</th><th class="p-3 text-left">PURPOSE</th><th class="p-3 text-left">TIMESTAMP</th></tr></thead><tbody>${x.data.map(l=>`<tr class="border-b"><td class="p-3 font-mono text-xs">#${String(l.id).padStart(4,'0')}</td><td class="p-3 font-medium">${esc(l.personName)}</td><td class="p-3">${badge(l.sacrament)}</td><td class="p-3">${esc(l.issuedTo)}</td><td class="p-3">${esc(l.purpose)}</td><td class="p-3 text-xs text-slate2-500">${esc(l.timestamp)}</td></tr>`).join('')||'<tr><td colspan="6" class="p-10 text-center text-slate2-500">No certificates have been issued yet.</td></tr>'}</tbody></table></div><div class="p-3 bg-paper text-xs text-slate2-500">${x.meta.total} log entries on record</div></div></section>`}
async function init(){try{me=(await apiCall('/auth/me')).data;render()}catch(e){login()}}

// Staff configuration UI. Server-side role checks remain the security boundary.
function shell(){let tabs=[['search','Search & Print Certificates'],['bulk','Bulk Data Ingestion'],['rapid','Rapid Data Entry'],['audit','Issuance Audit Logs'],...(me.role==='staff'?[['settings','Settings']]:[])];return `<header class="bg-navy-950 border-b border-navy-700 no-print"><div class="max-w-7xl mx-auto px-6 pt-5"><div class="flex justify-between items-center mb-5"><div class="flex gap-3 items-center"><div class="w-9 h-9 rounded-full border border-gold-400/60 text-gold-400 grid place-items-center font-cert">&#10013;</div><div><h1 class="text-slate-50 text-lg font-semibold leading-none">Parish Sacramental Registry System</h1><p class="text-xs mt-1 text-slate-400">Diocesan Record &amp; Certification Office</p></div></div><div class="text-sm text-slate2-300">Logged in as: <b class="text-white">${esc(me.full_name)}</b> <button id="logout" class="ml-3 underline">Logout</button></div></div><nav class="flex gap-7 text-sm">${tabs.filter(t=>me.role!=='viewer'||['search','audit'].includes(t[0])).map(t=>`<button data-tab="${t[0]}" class="tab ${tab===t[0]?'active':'text-slate-300'} pb-3 font-medium">${t[1]}</button>`).join('')}</nav></div></header><main class="max-w-7xl mx-auto px-6 py-8 no-print" id="content"></main>`}
async function render(){app.innerHTML=shell();$('#logout').onclick=async()=>{await apiCall('/auth/logout',{method:'POST'});me=null;login()};document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{tab=x.dataset.tab;render()});if(tab==='search')searchView();if(tab==='rapid')rapidView();if(tab==='bulk')bulkView();if(tab==='audit')auditView();if(tab==='settings')settingsView()}
function settingInput(label,name,value=''){return `<div><label class="field-label block mb-1">${label}</label><input name="${name}" value="${esc(value)}" class="w-full border border-slate2-300 rounded-md p-2 text-sm"></div>`}
function settingsView(){apiCall('/settings').then(x=>{let d=x?.data??x??{};d.parish??={};d.templates??=defaultTemplates();renderSettings(d)}).catch(e=>content.innerHTML=`<section class="bg-white border border-wine-600/30 rounded-lg p-5 text-wine-700"><b>Settings could not be loaded.</b><p class="text-sm mt-1">${esc(e.message)}</p></section>`)}
function defaultTemplates(){return Object.fromEntries(['Baptism','Communion','Confirmation','Marriage','Death'].map(s=>[s,{title_text:`Certificate of ${s}`,body_template:'This is to certify that {name} received the Sacrament of {sacrament} on {eventDate}.',footer_note:'Not valid without the parish dry seal.'}]))}
function renderSettings(data){let p=data.parish||{}, types=['Baptism','Communion','Confirmation','Marriage','Death'];content.innerHTML=`<section><h2 class="text-xl font-semibold">Parish Settings</h2><p class="text-sm text-slate2-500 mt-1 mb-5">Changes apply to every certificate generated after saving.</p><form id="identity" class="bg-white border border-slate2-300/70 rounded-lg shadow-sm p-6 mb-5"><h3 class="font-semibold mb-4">Parish Identity</h3><div class="grid md:grid-cols-2 gap-4">${settingInput('PARISH NAME','parish_name',p.parish_name)}${settingInput('DIOCESE NAME','diocese_name',p.diocese_name)}${settingInput('ADDRESS','address',p.address)}${settingInput('DEFAULT PRIEST NAME','default_priest_name',p.default_priest_name)}</div><div class="mt-5"><button class="bg-gold-600 text-white px-4 py-2 rounded-md text-sm font-semibold">Save Changes</button></div></form><section class="bg-white border border-slate2-300/70 rounded-lg shadow-sm p-6 mb-5"><h3 class="font-semibold mb-4">Seal &amp; Signature</h3><div class="grid md:grid-cols-2 gap-5">${uploadPanel('seal','Parish Seal',p.seal_image_path)}${uploadPanel('signature','Priest’s Signature',p.priest_signature_path)}</div></section><section class="bg-white border border-slate2-300/70 rounded-lg shadow-sm p-6"><h3 class="font-semibold">Certificate Wording</h3><p class="text-xs text-slate2-500 mt-1 mb-4">Choose one sacrament to edit; each template saves independently.</p><div class="flex flex-wrap gap-2 mb-5">${types.map((t,i)=>`<button data-template-tab="${t}" class="template-tab px-3 py-1.5 rounded-md text-sm ${i?'bg-paper':'bg-navy-800 text-white'}">${t}</button>`).join('')}</div><div id="template-editor"></div></section></section>`;$('#identity').onsubmit=saveIdentity;bindUpload('seal','seal');bindUpload('signature','priest-signature');document.querySelectorAll('[data-template-tab]').forEach(b=>b.onclick=()=>showTemplate(b.dataset.templateTab,data.templates));showTemplate('Baptism',data.templates)}
function uploadPanel(id,label,path){let src=path?`../${esc(path)}`:'';return `<div class="border-2 border-dashed border-slate2-300 rounded-lg p-4 text-center"><p class="field-label mb-3">${label.toUpperCase()}</p><div class="h-24 grid place-items-center mb-3">${src?`<img id="${id}-thumb" src="${src}" class="max-h-24 max-w-full object-contain">`:`<span id="${id}-thumb" class="text-xs text-slate2-500">No image uploaded</span>`}</div><input id="${id}-file" type="file" accept="image/png,image/jpeg" class="hidden"><button type="button" id="${id}-browse" class="bg-navy-800 text-white px-3 py-1.5 rounded-md text-xs font-semibold">Replace</button></div>`}
async function saveIdentity(e){e.preventDefault();try{let x=await apiCall('/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});renderSettings(x.data);alert('Parish identity saved.')}catch(err){alert(err.message)}}
function bindUpload(id,endpoint){$(`#${id}-browse`).onclick=()=>$(`#${id}-file`).click();$(`#${id}-file`).onchange=async e=>{let f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg'].includes(f.type)||f.size>2*1024*1024)return alert('Choose a PNG or JPEG image under 2MB.');let form=new FormData();form.append(id==='seal'?'seal':'signature',f);try{let x=await apiCall(`/settings/${endpoint}`,{method:'POST',body:form});renderSettings(x.data)}catch(err){alert(err.message)}}}
function showTemplate(type,templates){document.querySelectorAll('.template-tab').forEach(b=>b.className=`template-tab px-3 py-1.5 rounded-md text-sm ${b.dataset.templateTab===type?'bg-navy-800 text-white':'bg-paper'}`);let t=templates[type], chips=['{name}','{dob}','{fatherName}','{motherName}','{eventDate}','{spouse}','{sacrament}','{book}','{page}','{line}'];$('#template-editor').innerHTML=`<form id="template-form"><div class="grid gap-4">${settingInput('TITLE TEXT','title_text',t.title_text)}<div><label class="field-label block mb-1">BODY TEMPLATE</label><textarea id="body-template" name="body_template" rows="8" class="w-full border border-slate2-300 rounded-md p-3 text-sm font-mono">${esc(t.body_template)}</textarea><div class="flex flex-wrap gap-1.5 mt-2">${chips.map(c=>`<button type="button" data-chip="${c}" class="px-2 py-1 rounded bg-gold-100 text-gold-700 text-xs font-mono">${c}</button>`).join('')}</div><p class="text-xs text-slate2-500 mt-2">Available placeholders: click a token to insert it at the cursor.</p></div>${settingInput('FOOTER NOTE','footer_note',t.footer_note)}</div><div class="flex gap-3 mt-5"><button class="bg-gold-600 text-white px-4 py-2 rounded-md text-sm font-semibold">Save ${type} Template</button><button type="button" id="preview-template" class="text-gold-700 font-semibold text-sm">Preview sample certificate</button></div></form>`;document.querySelectorAll('[data-chip]').forEach(b=>b.onclick=()=>{let a=$('#body-template'),i=a.selectionStart;a.setRangeText(b.dataset.chip,i,a.selectionEnd,'end');a.focus()});$('#template-form').onsubmit=async e=>{e.preventDefault();try{let x=await apiCall(`/certificate-templates/${type}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});templates[type]=x.data;alert(`${type} template saved.`)}catch(err){alert(err.message)}};$('#preview-template').onclick=()=>previewTemplate(type)}
function previewTemplate(type){let form=$('#template-form'), d=Object.fromEntries(new FormData(form)), sample={'{name}':'Maria Santos','{dob}':'May 12, 1998','{fatherName}':'Jose Santos','{motherName}':'Ana Cruz','{eventDate}':'June 8, 2020','{spouse}':'Juan Reyes','{sacrament}':type,'{book}':'12','{page}':'45','{line}':'7'}, body=esc(d.body_template).replace(/\{(?:name|dob|fatherName|motherName|eventDate|spouse|sacrament|book|page|line)\}/g,m=>sample[m]);app.insertAdjacentHTML('beforeend',`<div id="template-preview" class="fixed inset-0 bg-ink/70 z-30 p-6 overflow-y-auto"><section class="bg-white max-w-2xl mx-auto rounded-lg shadow-2xl p-8 font-cert"><button id="close-template-preview" class="float-right text-sm">Close</button><p class="text-center text-xs text-wine-700">SAMPLE CERTIFICATE</p><h3 class="text-center text-xl font-semibold my-5">${esc(d.title_text)}</h3><p class="leading-8 text-justify">${body}</p><p class="text-center text-xs mt-10 pt-4 border-t border-dashed text-slate2-500">${esc(d.footer_note)}</p></section></div>`);$('#close-template-preview').onclick=()=>$('#template-preview').remove()}
function uploadPanel(id,label,path){let src=path?`${api}/settings/image/${id==='seal'?'seal':'signature'}?v=${Date.now()}`:'';return `<div class="border-2 border-dashed border-slate2-300 rounded-lg p-4 text-center"><p class="field-label mb-3">${label.toUpperCase()}</p><div class="h-24 grid place-items-center mb-3">${src?`<img id="${id}-thumb" src="${src}" class="max-h-24 max-w-full object-contain">`:`<span id="${id}-thumb" class="text-xs text-slate2-500">No image uploaded</span>`}</div><input id="${id}-file" type="file" accept="image/png,image/jpeg" class="hidden"><button type="button" id="${id}-browse" class="bg-navy-800 text-white px-3 py-1.5 rounded-md text-xs font-semibold">Replace</button></div>`}
function initials(name){return String(name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase()}
function navAvatar(){return me.avatar_path?`<img src="${api}/me/avatar?v=${Date.now()}" class="w-8 h-8 rounded-full object-cover" alt="">`:`<span class="w-8 h-8 rounded-full bg-gradient-to-br from-gold-400 to-gold-700 text-navy-950 grid place-items-center text-xs font-bold">${esc(initials(me.full_name))}</span>`}
function shell(){let tabs=[['search','Search & Print Certificates'],['bulk','Bulk Data Ingestion'],['rapid','Rapid Data Entry'],['audit','Issuance Audit Logs'],...(me.role==='staff'?[['settings','Settings']]:[])];return `<header class="bg-navy-950 border-b border-navy-700 no-print"><div class="max-w-7xl mx-auto px-6 pt-5"><div class="flex justify-between items-center mb-5"><div class="flex gap-3 items-center"><div class="w-9 h-9 rounded-full border border-gold-400/60 text-gold-400 grid place-items-center font-cert">&#10013;</div><div><h1 class="text-slate-50 text-lg font-semibold leading-none">Parish Sacramental Registry System</h1><p class="text-xs mt-1 text-slate-400">Diocesan Record &amp; Certification Office</p></div></div><div class="relative"><button id="profile-toggle" class="flex items-center gap-2 text-left"><span class="relative">${navAvatar()}<i class="absolute -right-0.5 -bottom-0.5 w-2.5 h-2.5 rounded-full bg-green-400 border-2 border-navy-950"></i></span><span class="hidden sm:block text-sm"><b class="block text-white leading-tight">${esc(me.full_name)}</b><small class="text-slate2-300 capitalize">${esc(me.role)}</small></span></button><div id="profile-menu" class="hidden absolute right-0 top-11 w-60 bg-white rounded-lg shadow-xl border border-slate2-300 z-20 p-2 text-sm"><div class="px-3 py-2 border-b mb-1"><b class="block">${esc(me.full_name)}</b><span class="text-xs text-slate2-500">${esc(me.email||me.username)}</span></div><button data-profile="view" class="w-full text-left px-3 py-2 rounded hover:bg-paper">My Profile</button><button data-profile="settings" class="w-full text-left px-3 py-2 rounded hover:bg-paper">Account Settings</button><button id="logout" class="w-full text-left px-3 py-2 rounded text-wine-700 hover:bg-wine-100">Log Out</button></div></div></div><nav class="flex gap-7 text-sm">${tabs.filter(t=>me.role!=='viewer'||['search','audit'].includes(t[0])).map(t=>`<button data-tab="${t[0]}" class="tab ${tab===t[0]?'active':'text-slate-300'} pb-3 font-medium">${t[1]}</button>`).join('')}</nav></div></header><main class="max-w-7xl mx-auto px-6 py-8 no-print" id="content"></main>`}
async function render(){app.innerHTML=shell();$('#logout').onclick=async()=>{await apiCall('/auth/logout',{method:'POST'});me=null;login()};$('#profile-toggle').onclick=()=>$('#profile-menu').classList.toggle('hidden');document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>profileModal(b.dataset.profile));document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{tab=x.dataset.tab;render()});if(tab==='search')searchView();if(tab==='rapid')rapidView();if(tab==='bulk')bulkView();if(tab==='audit')auditView();if(tab==='settings')settingsView()}
function profileModal(mode='view'){let readOnly=mode==='view';app.insertAdjacentHTML('beforeend',`<div id="profile-overlay" class="fixed inset-0 bg-ink/60 grid place-items-center z-30 px-4"><section class="bg-white rounded-lg shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto"><div class="p-5 border-b flex justify-between"><h3 class="font-semibold">${readOnly?'My Profile':'Account Settings'}</h3><button data-profile-close>&times;</button></div><div class="p-6">${readOnly?profileReadOnly():profileForm()}<div id="profile-error" class="hidden mt-4 p-3 rounded-md text-sm bg-wine-100 border border-wine-600/30 text-wine-700"></div></div></section></div>`);$('[data-profile-close]').onclick=closeProfile;if(readOnly)$('#profile-edit').onclick=()=>{closeProfile();profileModal('settings')};else bindProfileForm()}
function profileReadOnly(){return `<dl class="grid grid-cols-[100px_1fr] gap-y-3 text-sm"><dt class="text-slate2-500">Name</dt><dd>${esc(me.full_name)}</dd><dt class="text-slate2-500">Email</dt><dd>${esc(me.email||'Not provided')}</dd><dt class="text-slate2-500">Role</dt><dd class="capitalize">${esc(me.role)}</dd><dt class="text-slate2-500">Username</dt><dd>${esc(me.username)}</dd></dl><button id="profile-edit" class="mt-6 bg-gold-600 text-white px-4 py-2 rounded-md text-sm font-semibold">Edit</button>`}
function profileForm(){return `<form id="profile-info" class="space-y-4"><h4 class="font-semibold text-sm">Profile Info</h4><div><label class="field-label block mb-1">FULL NAME</label><input name="full_name" value="${esc(me.full_name)}" class="w-full border border-slate2-300 rounded-md p-2" required></div><div><label class="field-label block mb-1">EMAIL</label><input name="email" type="email" value="${esc(me.email||'')}" class="w-full border border-slate2-300 rounded-md p-2"></div><button class="bg-gold-600 text-white px-4 py-2 rounded-md text-sm font-semibold">Save Changes</button></form><form id="password-form" class="space-y-4 mt-7 pt-6 border-t"><h4 class="font-semibold text-sm">Change Password</h4><div><label class="field-label block mb-1">CURRENT PASSWORD</label><input name="current_password" type="password" class="w-full border border-slate2-300 rounded-md p-2" required></div><div><label class="field-label block mb-1">NEW PASSWORD</label><input name="new_password" type="password" minlength="8" class="w-full border border-slate2-300 rounded-md p-2" required></div><div><label class="field-label block mb-1">CONFIRM NEW PASSWORD</label><input name="confirm_password" type="password" minlength="8" class="w-full border border-slate2-300 rounded-md p-2" required></div><button class="bg-navy-800 text-white px-4 py-2 rounded-md text-sm font-semibold">Update Password</button></form><section class="mt-7 pt-6 border-t"><h4 class="font-semibold text-sm">Avatar</h4><div class="flex items-center gap-4 mt-3">${navAvatar()}<div><input id="avatar-file" type="file" accept="image/png,image/jpeg" class="hidden"><button type="button" id="avatar-browse" class="bg-navy-800 text-white px-3 py-1.5 rounded-md text-xs font-semibold">Upload / Replace</button><p class="text-xs text-slate2-500 mt-1">PNG or JPEG, up to 2MB.</p></div></div></section>`}
function profileError(message){let e=$('#profile-error');e.textContent=message;e.classList.remove('hidden')}
function bindProfileForm(){$('#profile-info').onsubmit=async e=>{e.preventDefault();try{let x=await apiCall('/me',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});me=x.data;render();profileModal('settings')}catch(err){profileError(err.message)}};$('#password-form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(d.new_password!==d.confirm_password)return profileError('New password and confirmation do not match.');try{await apiCall('/me/password',{method:'PUT',body:JSON.stringify(d)});e.target.reset();profileError('Password updated successfully.');$('#profile-error').className='mt-4 p-3 rounded-md text-sm bg-green-50 border border-green-200 text-green-800'}catch(err){profileError(err.message)}};$('#avatar-browse').onclick=()=>$('#avatar-file').click();$('#avatar-file').onchange=async e=>{let file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>2*1024*1024)return profileError('Choose a PNG or JPEG image under 2MB.');let f=new FormData();f.append('avatar',file);try{let x=await apiCall('/me/avatar',{method:'POST',body:f});me=x.data;render();profileModal('settings')}catch(err){profileError(err.message)}}}
function closeProfile(){$('#profile-overlay')?.remove()}
function roleMeta(role){return role==='admin'?['Administrator','bg-wine-100 text-wine-700 border-wine-600/30']:role==='viewer'?['Viewer','bg-slate2-100 text-slate2-700 border-slate2-300']:['Parish Staff','bg-navy-800/10 text-navy-800 border-navy-800/30']}
function navAvatar(){return me.avatar_path?`<img src="${api}/me/avatar?v=${Date.now()}" class="w-8 h-8 rounded-full object-cover" alt="">`:`<span class="w-8 h-8 rounded-full bg-gradient-to-br from-gold-400 to-gold-600 text-navy-950 grid place-items-center text-xs font-bold">${esc(initials(me.full_name))}</span>`}
function profileIcon(kind){return kind==='logout'?`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" class="w-4 h-4"><path d="M10 17l5-5-5-5M15 12H3M14 4h4a2 2 0 012 2v12a2 2 0 01-2 2h-4"/></svg>`:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" class="w-4 h-4"><circle cx="12" cy="8" r="4"/><path d="M4 21c.8-4 3.4-6 8-6s7.2 2 8 6"/></svg>`}
function enhanceProfileMenu(){let trigger=$('#profile-toggle'),menu=$('#profile-menu'),[role,badge]=roleMeta(me.role);trigger.className='flex items-center gap-2 text-left rounded-full px-2.5 py-1.5 -mr-2.5 hover:bg-white/5 focus:outline-none focus:ring-[3px] focus:ring-gold-400/30';let stack=trigger.querySelector('.hidden');if(stack)stack.innerHTML=`<b class="block text-sm font-medium text-slate-50 leading-tight">${esc(me.full_name)}</b><small class="block text-[11px] text-[#8fa0c2] leading-tight mt-0.5">${role}</small>`;trigger.insertAdjacentHTML('beforeend',`<svg id="profile-chevron" viewBox="0 0 24 24" fill="none" stroke="#8fa0c2" stroke-width="2" class="w-3.5 h-3.5 transition-transform duration-150" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>`);menu.className='hidden absolute right-0 top-[calc(100%+8px)] w-64 bg-white rounded-lg shadow-2xl border border-slate-200 z-50 text-sm overflow-hidden';menu.innerHTML=`<div class="bg-paper border-b border-slate-200 p-4"><b class="block text-sm font-semibold text-ink">${esc(me.full_name)}</b><span class="block text-xs text-slate2-500 mt-0.5">${esc(me.email||me.username)}</span><span class="inline-flex mt-2 px-2 py-0.5 rounded-full text-[11px] font-semibold border ${badge}">${role}</span></div><div class="py-1.5"><button data-profile="view" class="w-full flex items-center gap-2.5 text-left px-4 py-2 text-ink hover:bg-paper focus:bg-paper focus:outline-none">${profileIcon('profile')}<span>My Profile</span></button><button data-profile="settings" class="w-full flex items-center gap-2.5 text-left px-4 py-2 text-ink hover:bg-paper focus:bg-paper focus:outline-none">${profileIcon('profile')}<span>Account Settings</span></button></div><div class="border-t border-slate-200 py-1.5"><button id="logout" class="w-full flex items-center gap-2.5 text-left px-4 py-2 text-wine-700 hover:bg-wine-100 focus:bg-wine-100 focus:outline-none">${profileIcon('logout')}<span>Log Out</span></button></div>`;$('#logout').onclick=async()=>{await apiCall('/auth/logout',{method:'POST'});me=null;login()};document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{menu.classList.add('hidden');profileModal(b.dataset.profile)});trigger.onclick=e=>{e.stopPropagation();let open=menu.classList.toggle('hidden')===false;$('#profile-chevron').classList.toggle('rotate-180',open);trigger.classList.toggle('bg-white/5',open)};document.onclick=e=>{if(!trigger.contains(e.target)&&!menu.contains(e.target)){menu.classList.add('hidden');$('#profile-chevron').classList.remove('rotate-180');trigger.classList.remove('bg-white/5')}};document.onkeydown=e=>{if(e.key==='Escape'){menu.classList.add('hidden');$('#profile-chevron').classList.remove('rotate-180');trigger.classList.remove('bg-white/5');trigger.focus()}}}
async function render(){app.innerHTML=shell();enhanceProfileMenu();document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{tab=x.dataset.tab;render()});if(tab==='search')searchView();if(tab==='rapid')rapidView();if(tab==='bulk')bulkView();if(tab==='audit')auditView();if(tab==='settings')settingsView()}
async function certificatePreview(r){selected=r;let cfg={parish:{},templates:{}};try{let x=await apiCall('/certificate-preview-settings');cfg=x.data??x}catch(e){console.warn('Certificate preview settings unavailable',e)}let p=cfg.parish||{},t=(cfg.templates||{})[r.sacrament]||{title_text:r.sacrament==='Communion'?'Certificate of First Holy Communion':`Certificate of ${r.sacrament}`,body_template:'This is to certify that {name} received the Sacrament of {sacrament} on {eventDate}.',footer_note:'Not valid without the parish dry seal.'},date=v=>v?new Date(v+'T00:00:00').toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'}):'—',name=full(r),token=v=>`<strong class="text-[#151b2b]">${esc(v)}</strong>`,tokens={'{name}':token(name),'{dob}':token(date(r.dob)),'{fatherName}':token(r.fatherName),'{motherName}':token(r.motherName),'{eventDate}':token(date(r.eventDate)),'{spouse}':token(r.spouse),'{sacrament}':token(r.sacrament),'{book}':esc(r.book),'{page}':esc(r.page),'{line}':esc(r.line)},body=esc(t.body_template).replace(/\{name\}|\{dob\}|\{fatherName\}|\{motherName\}|\{eventDate\}|\{spouse\}|\{sacrament\}|\{book\}|\{page\}|\{line\}/g,m=>tokens[m]),notes=r.marginNotes?`<div class="mb-6 text-sm bg-wine-100 border-l-[3px] border-wine-700 p-3"><b class="block text-xs text-wine-700">CANONICAL MARGIN NOTES</b>${esc(r.marginNotes)}</div>`:'',seal=p.seal_image_path?`<img src="${api}/certificate-preview-image/seal" class="w-24 h-24 object-contain mx-auto mb-5" alt="Parish seal">`:`<div class="seal mx-auto mb-5"><div>PARISH<br>SEAL</div></div>`,signature=p.priest_signature_path?`<img src="${api}/certificate-preview-image/signature" class="w-48 h-12 object-contain object-left-bottom mb-1" alt="Priest signature">`:'<div class="h-12"></div>',priest=r.minister||p.default_priest_name||'';$('#certificate-preview')?.remove();app.insertAdjacentHTML('beforeend',`<div id="certificate-preview" class="fixed inset-0 bg-ink/70 z-30 px-4 py-8 overflow-y-auto"><section class="max-w-3xl mx-auto"><div class="flex justify-end gap-2 mb-3"><button data-close-preview class="px-4 py-2 text-sm rounded-md bg-navy-800 text-white font-medium">Close</button><button id="print-certificate" class="px-4 py-2 text-sm rounded-md bg-gold-600 text-white font-semibold">Print Certificate</button></div><article class="bg-white shadow-2xl mx-auto p-12 md:p-14 font-cert text-[#1c2431]" style="max-width:720px"><header class="text-center border-b-2 border-gold-600 pb-5 mb-6"><p class="text-xs tracking-wide text-wine-700">${esc(p.diocese_name||'')}</p><h2 class="text-2xl font-semibold mt-1">${esc(p.parish_name||'')}</h2><p class="text-xs mt-1 text-slate2-500">${esc(p.address||'')}</p></header>${seal}<h3 class="text-center text-xl font-semibold mb-6 tracking-wide">${esc(t.title_text)}</h3><p class="text-[15px] leading-8 text-justify">${body}</p><div class="grid grid-cols-3 gap-3 my-7 py-3 border-y border-[#d8d2c2] text-sm"><div><span class="block text-xs text-slate2-500">Book No.</span><b>${esc(r.book)}</b></div><div><span class="block text-xs text-slate2-500">Page No.</span><b>${esc(r.page)}</b></div><div><span class="block text-xs text-slate2-500">Line Entry No.</span><b>${esc(r.line)}</b></div></div>${notes}<div class="flex items-end justify-between mt-14 text-sm"><div>${signature}<div class="border-t border-ink w-56 mb-1"></div><b>${esc(priest)}</b><p class="text-xs text-slate2-500">Officiating Priest / Parish Priest</p></div><div class="text-right"><div class="border-t border-ink w-40 mb-1 ml-auto"></div><p class="text-xs text-slate2-500">Date Issued</p><b>${date(new Date().toISOString().slice(0,10))}</b></div></div><p class="text-center text-xs mt-10 pt-4 border-t border-dashed border-slate2-300 text-slate2-500">Issued to <b class="text-ink">____________________</b> for the purpose of <b class="text-ink">Personal Record</b>. ${esc(t.footer_note)}</p></article></section></div>`);$('[data-close-preview]').onclick=()=>$('#certificate-preview').remove();$('#print-certificate').onclick=()=>issuePreview()}
function uploadPanel(id,label,path){let src=path?`${api}/settings/image/${id==='seal'?'seal':'signature'}?v=${Date.now()}`:'',fallback=id==='seal'?`<div id="${id}-thumb" class="seal"><div>PARISH<br>SEAL</div></div>`:`<span id="${id}-thumb" class="text-xs text-slate2-500">No image uploaded</span>`;return `<div class="border-2 border-dashed border-slate2-300 rounded-lg p-4 text-center"><p class="field-label mb-3">${label.toUpperCase()}</p><div class="h-24 grid place-items-center mb-3">${src?`<img id="${id}-thumb" src="${src}" class="max-h-24 max-w-full object-contain">`:fallback}</div><p class="text-xs text-slate2-500 mb-3">${id==='seal'&&!path?'Default parish seal':' '}</p><input id="${id}-file" type="file" accept="image/png,image/jpeg" class="hidden"><button type="button" id="${id}-browse" class="bg-navy-800 text-white px-3 py-1.5 rounded-md text-xs font-semibold">${path?'Replace':'Upload / Replace'}</button></div>`}
var requestRows=[],requestStatusFilter='all',requestQuery='';
const requestStatusLabels={submitted:'Submitted',under_review:'Under Review',needs_more_info:'Needs More Information',approved:'Approved',ready_for_pickup:'Ready for Pickup',released:'Released',rejected:'Rejected',not_found:'Not Found'};
const requestStatusColors={submitted:'bg-slate2-100 text-slate2-700 border-slate2-300',under_review:'bg-navy-800/10 text-navy-800 border-navy-800/30',needs_more_info:'bg-gold-100 text-gold-700 border-gold-400/50',approved:'bg-green-50 text-green-800 border-green-200',ready_for_pickup:'bg-green-50 text-green-800 border-green-200',released:'bg-slate2-100 text-slate2-700 border-slate2-300',rejected:'bg-wine-100 text-wine-700 border-wine-600/30',not_found:'bg-wine-100 text-wine-700 border-wine-600/30'};
function requestBadge(status){return `<span class="px-2 py-0.5 rounded-full text-xs font-semibold border ${requestStatusColors[status]||''}">${esc(requestStatusLabels[status]||status)}</span>`}
function requestPersonName(r){return `${r.person_first_name||''} ${r.person_middle_name?r.person_middle_name+' ':''}${r.person_last_name||''}`.replace(/\s+/g,' ').trim()}
function shell(){let tabs=[...(me.role==='admin'||me.role==='staff'?[['requests','Certificate Requests']]:[]),['search','Search & Print Certificates'],['bulk','Bulk Data Ingestion'],['rapid','Rapid Data Entry'],['audit','Issuance Audit Logs'],...(me.role==='staff'?[['settings','Settings']]:[])];return `<header class="bg-navy-950 border-b border-navy-700 no-print"><div class="max-w-7xl mx-auto px-6 pt-5"><div class="flex justify-between items-center mb-5"><div class="flex gap-3 items-center"><div class="w-9 h-9 rounded-full border border-gold-400/60 text-gold-400 grid place-items-center font-cert">&#10013;</div><div><h1 class="text-slate-50 text-lg font-semibold leading-none">Parish Sacramental Registry System</h1><p class="text-xs mt-1 text-slate-400">Diocesan Record &amp; Certification Office</p></div></div><div class="relative"><button id="profile-toggle" class="flex items-center gap-2 text-left"><span class="relative">${navAvatar()}<i class="absolute -right-0.5 -bottom-0.5 w-2.5 h-2.5 rounded-full bg-green-400 border-2 border-navy-950"></i></span><span class="hidden sm:block text-sm"><b class="block text-white leading-tight">${esc(me.full_name)}</b><small class="text-slate2-300 capitalize">${esc(me.role)}</small></span></button><div id="profile-menu" class="hidden absolute right-0 top-11 w-60 bg-white rounded-lg shadow-xl border border-slate2-300 z-20 p-2 text-sm"><div class="px-3 py-2 border-b mb-1"><b class="block">${esc(me.full_name)}</b><span class="text-xs text-slate2-500">${esc(me.email||me.username)}</span></div><button data-profile="view" class="w-full text-left px-3 py-2 rounded hover:bg-paper">My Profile</button><button data-profile="settings" class="w-full text-left px-3 py-2 rounded hover:bg-paper">Account Settings</button><button id="logout" class="w-full text-left px-3 py-2 rounded text-wine-700 hover:bg-wine-100">Log Out</button></div></div></div><nav class="flex gap-7 text-sm overflow-x-auto">${tabs.filter(t=>me.role!=='viewer'||['search','audit'].includes(t[0])).map(t=>`<button data-tab="${t[0]}" class="tab whitespace-nowrap ${tab===t[0]?'active':'text-slate-300'} pb-3 font-medium">${t[1]}</button>`).join('')}</nav></div></header><main class="max-w-7xl mx-auto px-6 py-8 no-print" id="content"></main>`}
async function render(){app.innerHTML=shell();enhanceProfileMenu();document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{tab=x.dataset.tab;render()});if(tab==='requests')requestsView();if(tab==='search')searchView();if(tab==='rapid')rapidView();if(tab==='bulk')bulkView();if(tab==='audit')auditView();if(tab==='settings')settingsView()}
async function requestsView(){let params=new URLSearchParams({status:requestStatusFilter,q:requestQuery});let x=await apiCall('/certificate-requests?'+params.toString());requestRows=x.data;content.innerHTML=`<section><div class="flex flex-col md:flex-row md:items-end md:justify-between gap-4 mb-5"><div><h2 class="text-xl font-semibold">Certificate Requests</h2><p class="text-sm text-slate2-500 mt-1">Review public requests, match them to registry records, and update release status.</p></div><a href="/certificate-request" target="_blank" class="text-sm font-semibold text-gold-700">Open public portal</a></div><form id="request-filters" class="bg-white border border-slate2-300/70 rounded-lg p-4 mb-5 shadow-sm grid md:grid-cols-[1fr_220px_auto] gap-3"><input id="request-query" value="${esc(requestQuery)}" class="border border-slate2-300 rounded-md p-2.5 text-sm" placeholder="Search tracking code, requester, phone, or name"><select id="request-status" class="border border-slate2-300 rounded-md p-2.5 text-sm"><option value="all">All statuses</option>${Object.entries(requestStatusLabels).map(([k,v])=>`<option value="${k}" ${requestStatusFilter===k?'selected':''}>${v}</option>`).join('')}</select><button class="bg-navy-800 text-white px-4 py-2 rounded-md text-sm font-semibold">Filter</button></form><div class="bg-white border border-slate2-300/70 rounded-lg shadow-sm overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-navy-900 text-slate-200 text-left"><tr><th class="p-3 text-xs">TRACKING</th><th class="p-3 text-xs">REQUESTER</th><th class="p-3 text-xs">CERTIFICATE</th><th class="p-3 text-xs">PERSON</th><th class="p-3 text-xs">STATUS</th><th class="p-3 text-xs">SUBMITTED</th><th class="p-3"></th></tr></thead><tbody>${requestRows.map(r=>`<tr class="border-b border-slate2-100 hover:bg-paper/70"><td class="p-3 font-mono text-xs">${esc(r.tracking_code)}</td><td class="p-3"><b>${esc(r.requester_name)}</b><small class="block text-slate2-500">${esc(r.requester_phone)}</small></td><td class="p-3">${badge(r.sacrament_type)}</td><td class="p-3">${esc(requestPersonName(r))}<small class="block text-slate2-500">${esc(r.event_date||r.event_year||'Date not supplied')}</small></td><td class="p-3">${requestBadge(r.status)}</td><td class="p-3 text-xs text-slate2-500">${esc(r.submitted_at||'')}</td><td class="p-3 text-right"><button data-view-request="${r.id}" class="bg-navy-800 text-white px-3 py-1.5 rounded-md text-xs font-semibold">Review</button></td></tr>`).join('')||'<tr><td colspan="7" class="p-10 text-center text-slate2-500">No certificate requests match this filter.</td></tr>'}</tbody></table></div><div class="px-4 py-2.5 bg-paper border-t text-xs text-slate2-500">${x.meta.total} request${x.meta.total===1?'':'s'} shown</div></div></section>`;$('#request-filters').onsubmit=e=>{e.preventDefault();requestQuery=$('#request-query').value;requestStatusFilter=$('#request-status').value;requestsView()};$('#request-status').onchange=e=>{requestStatusFilter=e.target.value;requestsView()};document.querySelectorAll('[data-view-request]').forEach(b=>b.onclick=()=>requestModal(b.dataset.viewRequest))}
async function requestModal(id){let x=await apiCall(`/certificate-requests/${id}`),r=x.data;$('#request-overlay')?.remove();app.insertAdjacentHTML('beforeend',`<div id="request-overlay" class="fixed inset-0 bg-ink/60 z-30 px-4 py-6 overflow-y-auto"><section class="bg-white rounded-lg shadow-2xl w-full max-w-5xl mx-auto"><div class="p-5 border-b flex justify-between gap-4"><div><h3 class="font-semibold">Request ${esc(r.tracking_code)}</h3><p class="text-xs text-slate2-500 mt-1">${esc(r.requester_name)} / ${esc(r.requester_phone)}</p></div><button data-request-close class="text-xl leading-none">&times;</button></div><div class="p-6 grid lg:grid-cols-[1fr_360px] gap-6"><div class="space-y-5"><section class="bg-paper border border-slate2-300/70 rounded-lg p-4"><h4 class="font-semibold text-sm mb-3">Submitted Details</h4><dl class="grid md:grid-cols-2 gap-x-5 gap-y-3 text-sm"><div><dt class="text-xs text-slate2-500">Certificate</dt><dd>${badge(r.sacrament_type)}</dd></div><div><dt class="text-xs text-slate2-500">Purpose</dt><dd>${esc(r.purpose)}</dd></div><div><dt class="text-xs text-slate2-500">Person</dt><dd>${esc(requestPersonName(r))}</dd></div><div><dt class="text-xs text-slate2-500">Birth Date</dt><dd>${esc(r.person_date_of_birth||'Not supplied')}</dd></div><div><dt class="text-xs text-slate2-500">Father</dt><dd>${esc(r.father_name||'Not supplied')}</dd></div><div><dt class="text-xs text-slate2-500">Mother</dt><dd>${esc(r.mother_maiden_name||'Not supplied')}</dd></div><div><dt class="text-xs text-slate2-500">Sacrament Date</dt><dd>${esc(r.event_date||r.event_year||'Not supplied')}</dd></div><div><dt class="text-xs text-slate2-500">Release</dt><dd>${esc(r.delivery_method)}</dd></div></dl>${r.notes?`<p class="mt-4 text-sm border-t pt-3">${esc(r.notes)}</p>`:''}</section><section><div class="flex items-center justify-between mb-3"><h4 class="font-semibold text-sm">Possible Registry Matches</h4><button id="find-request-matches" class="text-xs font-semibold text-gold-700">Find matches</button></div><div id="request-matches" class="border border-slate2-300/70 rounded-lg overflow-hidden bg-white"><p class="p-4 text-sm text-slate2-500">Search for possible matches, then choose one to link.</p></div></section><section><h4 class="font-semibold text-sm mb-3">Status History</h4><div class="grid gap-2">${(r.status_logs||[]).map(l=>`<div class="flex gap-3 text-sm"><span class="w-2.5 h-2.5 rounded-full bg-gold-600 mt-1.5"></span><div><b>${esc(requestStatusLabels[l.status]||l.status)}</b><p class="text-xs text-slate2-500">${esc(l.created_at||'')}${l.changed_by?' by '+esc(l.changed_by):''}</p></div></div>`).join('')||'<p class="text-sm text-slate2-500">No status updates yet.</p>'}</div></section></div><form id="request-update" class="space-y-4"><div><label class="field-label block mb-1">STATUS</label><select id="request-modal-status" class="w-full border border-slate2-300 rounded-md p-2 text-sm">${Object.entries(requestStatusLabels).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select></div><div><label class="field-label block mb-1">LINKED RECORD ID</label><input id="request-record-id" value="${esc(r.sacramental_record_id||'')}" class="w-full border border-slate2-300 rounded-md p-2 text-sm" placeholder="Record ID"><p id="request-record-label" class="text-xs text-slate2-500 mt-1">${r.record?esc(`${r.record.personName} / Bk ${r.record.book} Pg ${r.record.page} Ln ${r.record.line}`):'No record linked yet'}</p></div><div><label class="field-label block mb-1">PUBLIC NOTE</label><textarea id="request-public-note" rows="4" class="w-full border border-slate2-300 rounded-md p-2 text-sm" placeholder="Shown to requester on tracking page">${esc(r.public_note||'')}</textarea></div><div><label class="field-label block mb-1">INTERNAL NOTES</label><textarea id="request-staff-notes" rows="5" class="w-full border border-slate2-300 rounded-md p-2 text-sm">${esc(r.staff_notes||'')}</textarea></div><div class="grid gap-2 pt-2"><button class="bg-gold-600 text-white px-4 py-2 rounded-md text-sm font-semibold">Save Request</button><button type="button" id="issue-request" class="bg-navy-800 text-white px-4 py-2 rounded-md text-sm font-semibold ${r.sacramental_record_id?'':'opacity-50'}">Generate Certificate</button>${r.has_attachment?`<button type="button" id="view-attachment" class="border border-slate2-300 px-4 py-2 rounded-md text-sm font-semibold">View Attachment</button>`:''}</div><div id="request-save-message" class="hidden p-3 rounded-md text-sm"></div></form></div></section></div>`);$('[data-request-close]').onclick=()=>$('#request-overlay').remove();$('#request-update').onsubmit=e=>saveRequestUpdate(e,r.id);$('#find-request-matches').onclick=()=>findRequestMatches(r);$('#issue-request').onclick=()=>issueRequest(r.id);if(r.has_attachment)$('#view-attachment').onclick=()=>window.open(`${api}/certificate-requests/${r.id}/attachment`,'_blank')}
async function findRequestMatches(r){let box=$('#request-matches');box.innerHTML='<p class="p-4 text-sm text-slate2-500">Searching registry...</p>';let q=r.person_last_name||r.person_first_name||'';try{let x=await apiCall('/records?q='+encodeURIComponent(q));let rows=(x.data||[]).filter(v=>!r.sacrament_type||v.sacrament===r.sacrament_type).slice(0,10);box.innerHTML=`<div class="overflow-x-auto"><table class="w-full text-sm"><tbody>${rows.map(v=>`<tr class="border-b"><td class="p-3"><b>${esc(full(v))}</b><small class="block text-slate2-500">${esc(v.sacrament)} / ${esc(v.eventDate)} / Bk ${esc(v.book)} Pg ${esc(v.page)} Ln ${esc(v.line)}</small></td><td class="p-3 text-right"><button data-pick-record="${v.id}" data-label="${esc(`${full(v)} / Bk ${v.book} Pg ${v.page} Ln ${v.line}`)}" class="bg-navy-800 text-white px-3 py-1.5 rounded-md text-xs font-semibold">Link</button></td></tr>`).join('')||'<tr><td class="p-4 text-slate2-500">No likely matches found.</td></tr>'}</tbody></table></div>`;document.querySelectorAll('[data-pick-record]').forEach(b=>b.onclick=()=>{$('#request-record-id').value=b.dataset.pickRecord;$('#request-record-label').textContent=b.dataset.label})}catch(err){box.innerHTML=`<p class="p-4 text-sm text-wine-700">${esc(err.message)}</p>`}}
async function saveRequestUpdate(e,id){e.preventDefault();let msg=$('#request-save-message');msg.className='p-3 rounded-md text-sm bg-paper border border-slate2-300 text-slate2-700';msg.textContent='Saving...';try{await apiCall(`/certificate-requests/${id}`,{method:'PUT',body:JSON.stringify({status:$('#request-modal-status').value,sacramental_record_id:$('#request-record-id').value||null,public_note:$('#request-public-note').value,staff_notes:$('#request-staff-notes').value})});msg.className='p-3 rounded-md text-sm bg-green-50 border border-green-200 text-green-800';msg.textContent='Saved.';await requestsView()}catch(err){msg.className='p-3 rounded-md text-sm bg-wine-100 border border-wine-600/30 text-wine-700';msg.textContent=err.message}}
async function issueRequest(id){let w=window.open('','_blank');try{let x=await apiCall(`/certificate-requests/${id}/issue`,{method:'POST'});let url=`${api}/records/${x.data.record_id}/certificate.pdf?log_id=${x.data.log_id}`;if(w)w.location=url;else window.location.assign(url);$('#request-overlay')?.remove();await requestsView()}catch(err){w?.close();alert(err.message)}}
init();
